
(function(){const { $, read, write, uid, esc, date, today, notify }=window.OP;const KEY='np_tareas_proyectos_pymes_v1';let state=read(KEY,{projects:[],tasks:[]});const statuses=['Pendiente','En curso','Bloqueada','Terminada'];function persist(){write(KEY,state);render()}function render(){const open=state.tasks.filter(t=>t.status!=='Terminada'),done=state.tasks.filter(t=>t.status==='Terminada').length,overdue=open.filter(t=>t.due&&t.due<today()).length;$('[data-kpi="projects"]').textContent=state.projects.length;$('[data-kpi="open"]').textContent=open.length;$('[data-kpi="overdue"]').textContent=overdue;$('[data-kpi="done"]').textContent=done;const opts='<option value="">Sin proyecto</option>'+state.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');const old=$('#taskProject').value;$('#taskProject').innerHTML=opts;$('#taskProject').value=old;const oldF=$('#taskProjectFilter').value;$('#taskProjectFilter').innerHTML='<option value="all">Todos los proyectos</option>'+state.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('#taskProjectFilter').value=oldF;const filter=$('#taskProjectFilter').value;$('#taskBoard').innerHTML=statuses.map(s=>{const tasks=state.tasks.filter(t=>t.status===s&&(filter==='all'||t.projectId===filter));return `<div class="op-lane"><h4>${s}<span>${tasks.length}</span></h4>${tasks.length?tasks.map(t=>`<article class="op-item"><strong>${esc(t.name)}</strong><small>${esc(t.projectName||'Sin proyecto')} · ${esc(t.owner||'Sin responsable')}</small><small class="${t.due&&t.due<today()&&s!=='Terminada'?'op-danger-text':''}">${t.due?`Límite: ${date(t.due)}`:'Sin fecha'}</small><span class="op-tag ${t.priority==='Alta'?'danger':t.priority==='Baja'?'good':'warn'}">${esc(t.priority)}</span><select data-status="${esc(t.id)}">${statuses.map(x=>`<option ${x===t.status?'selected':''}>${x}</option>`).join('')}</select><button class="op-button danger" data-delete-task="${esc(t.id)}">Eliminar</button></article>`).join(''):'<p class="op-muted">Sin tareas</p>'}</div>`}).join('');$('#projectsTable').innerHTML=state.projects.length?`<div class="op-table-wrap"><table class="op-table"><thead><tr><th>Proyecto</th><th>Cliente / área</th><th>Entrega</th><th>Tareas</th><th></th></tr></thead><tbody>${state.projects.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br><small>${esc(p.notes||'')}</small></td><td>${esc(p.client)}</td><td>${date(p.due)}</td><td>${state.tasks.filter(t=>t.projectId===p.id&&t.status==='Terminada').length}/${state.tasks.filter(t=>t.projectId===p.id).length} terminadas</td><td><button class="op-button danger" data-delete-project="${esc(p.id)}">Eliminar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="op-empty">Aún no hay proyectos.</div>'}$('#projectForm').addEventListener('submit',e=>{e.preventDefault();const p={id:uid(),name:$('#projectName').value.trim(),client:$('#projectClient').value.trim(),due:$('#projectDue').value,notes:$('#projectNotes').value.trim(),createdAt:new Date().toISOString()};if(!p.name)return;state.projects.unshift(p);e.target.reset();persist();notify('Proyecto creado.','good')});$('#taskForm').addEventListener('submit',e=>{e.preventDefault();const p=state.projects.find(x=>x.id===$('#taskProject').value);const t={id:uid(),name:$('#taskName').value.trim(),projectId:p?.id||'',projectName:p?.name||'',owner:$('#taskOwner').value.trim(),priority:$('#taskPriority').value,due:$('#taskDue').value,status:'Pendiente',notes:$('#taskNotes').value.trim(),createdAt:new Date().toISOString()};if(!t.name)return;state.tasks.unshift(t);e.target.reset();persist();notify('Tarea añadida.','good')});$('#taskProjectFilter').addEventListener('change',render);document.addEventListener('change',e=>{if(e.target.matches('[data-status]')){const t=state.tasks.find(x=>x.id===e.target.dataset.status);if(t){t.status=e.target.value;persist();notify('Estado actualizado.','good')}}});document.addEventListener('click',e=>{const dt=e.target.closest('[data-delete-task]')?.dataset.deleteTask;if(dt&&confirm('¿Eliminar esta tarea?')){state.tasks=state.tasks.filter(t=>t.id!==dt);persist()}const dp=e.target.closest('[data-delete-project]')?.dataset.deleteProject;if(dp&&confirm('¿Eliminar el proyecto y sus tareas?')){state.projects=state.projects.filter(p=>p.id!==dp);state.tasks=state.tasks.filter(t=>t.projectId!==dp);persist()}});$('#clearTasks').addEventListener('click',()=>{if(confirm('¿Eliminar todos los proyectos y tareas?')){state={projects:[],tasks:[]};persist();notify('Registro de proyectos vacío.')}});render()})();